import json
from typing import Any, Dict

def _offers_of(obj):
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        out = []
        for i, o in enumerate(offers, start=1):
            if not isinstance(o, dict):
                continue
            e = dict(o)
            e.setdefault('offer_seq', i)
            out.append(e)
        return out
    return [obj]

def _join(v):
    if isinstance(v, list):
        return ','.join(str(x) for x in v if str(x))
    return str(v or '')

def _sales_lines(raw):
    # 清单 JSON（销售品名→{offerId,location,sheet_name}）→ (编号逐行文本, 首品名)
    obj = raw
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if not isinstance(obj, dict):
        return str(raw or ''), ''
    lines = []
    first_name = ''
    for i, (name, item) in enumerate(obj.items(), start=1):
        info = item if isinstance(item, dict) else {}
        offer_id = str(info.get('offerId') or info.get('offer_id') or '')
        sheet = str(info.get('sheet_name') or '')
        if not first_name:
            first_name = str(name)
        lines.append('%d. %s（销售品ID=%s，Sheet=%s）' % (i, name, offer_id, sheet))
    return '\n'.join(lines), first_name

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    request_ids = ''
    offers_json = '[]'
    sales_list_text = ''
    offer_name = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            offers = _offers_of(inner)
            if offers:
                offer_id = str(offers[0].get('offer_id') or offers[0].get('offerId') or '')
            all_ids = []
            norm = []
            for i, o in enumerate(offers, start=1):
                rid = o.get('requestIds') or o.get('request_ids') or o.get('request_id') or ''
                ids = [x for x in _join(rid).split(',') if x]
                all_ids += ids
                seq = o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i
                one = {'offer_seq': seq,
                       'offer_id': str(o.get('offer_id') or o.get('offerId') or ''),
                       'requestIds': ','.join(ids),
                       'sales_id': str(o.get('sales_id') or ''),
                       'file_id': str(o.get('file_id') or '')}
                # V3.14：透传权威 name/quantity，供 4b 结构化封包按名册合并进 spec offers[]
                if str(o.get('name') or '').strip():
                    one['name'] = str(o.get('name')).strip()
                if o.get('quantity') not in (None, ''):
                    one['quantity'] = o.get('quantity')
                norm.append(one)
            if not all_ids:
                rid = inner.get('requestIds') or inner.get('request_ids') or ''
                all_ids = [x for x in _join(rid).split(',') if x]
            request_ids = ','.join(all_ids)
            offers_json = json.dumps(norm, ensure_ascii=False)
            sales_list_text, offer_name = _sales_lines(inner.get('sales_id'))
            if not offer_id and offer_name:
                offer_id = offer_name
    except Exception:
        offer_id = ''
        request_ids = ''
        offers_json = '[]'
        sales_list_text = ''
    ret: Output = {
        "record_json": record_json,
        "offer_id": offer_id,
        "offer_name": offer_name,
        "requestIds": request_ids,
        "offers": offers_json,
        "sales_list_text": sales_list_text
    }
    return ret

import json
import asyncio
import urllib.request
from typing import Any, Dict

SQL_URL = 'http://172.30.8.52:6174/api/v1/appstore/audit/sql-query'
INTERVAL = 5
MAX_RETRY = 60
MAX_CONSECUTIVE_FAIL = 5
SQL_ID_FINISH = '20260626001'

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _first_sql_row(resp):
    # B4 返回 {resultCode, execute_sql_resp:[{...}]}；完成标志/结论在首行内，需解包
    if not isinstance(resp, dict):
        return {}
    rows = resp.get('execute_sql_resp') or resp.get('executeSqlResp') or []
    if isinstance(rows, list) and rows and isinstance(rows[0], dict):
        return rows[0]
    if isinstance(rows, dict):
        return rows
    return resp

def _is_finished(request_ids):
    # 单品完成判定：查询其 requestIds，返回 (ok, finished)
    if not request_ids:
        return True, True
    try:
        body = json.dumps({'sqlId': SQL_ID_FINISH,
                           'params': 'requestIds:' + request_ids}).encode('utf-8')
        req = urllib.request.Request(SQL_URL, data=body,
                                     headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
    except Exception:
        return False, False
    if not isinstance(resp, dict):
        return False, False
    row = _first_sql_row(resp)
    finished = str(row.get('isAllFinished', row.get('finished', ''))).lower()
    return True, finished in ('y', 'yes', 'true', '1')

async def main(args):
    p = args.params
    offers = [o for o in _load(p.get('offers')) if isinstance(o, dict)]
    if not offers:
        # 兼容：顶层直接给逗号拼接的 requestIds
        rid = str(p.get('requestIds') or '')
        if rid:
            offers = [{'offer_seq': 1, 'offer_id': '', 'requestIds': rid}]
    if not offers:
        ret: Output = {'completed': 'false',
                       'fail_reason': '缺少 requestIds，请先发起稽核（环节4a）', 'offers': '[]'}
        return ret
    norm = []
    for i, o in enumerate(offers, start=1):
        seq = o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i
        rid = o.get('requestIds') or o.get('request_ids') or o.get('request_id') or ''
        if isinstance(rid, list):
            rid = ','.join(str(x) for x in rid if str(x))
        norm.append({'offer_seq': seq,
                     'offer_id': str(o.get('offer_id') or o.get('offerId') or ''),
                     'requestIds': str(rid or '')})
    consecutive_fail = 0
    for i in range(MAX_RETRY):
        all_done = True
        round_ok = True
        for o in norm:
            ok, finished = _is_finished(o['requestIds'])
            if not ok:
                round_ok = False
                break
            if not finished:
                all_done = False
                break
        if not round_ok:
            consecutive_fail += 1
            if consecutive_fail >= MAX_CONSECUTIVE_FAIL:
                ret: Output = {'completed': 'false',
                               'fail_reason': '连续查询失败5次，转人工',
                               'offers': json.dumps(norm, ensure_ascii=False)}
                return ret
            await asyncio.sleep(INTERVAL)
            continue
        consecutive_fail = 0
        if all_done:
            ret: Output = {'completed': 'true', 'fail_reason': '',
                           'offers': json.dumps(norm, ensure_ascii=False)}
            return ret
        await asyncio.sleep(INTERVAL)
    ret: Output = {'completed': 'false',
                   'fail_reason': '稽核处理中，请稍后回复【查询稽核结果】续查',
                   'offers': json.dumps(norm, ensure_ascii=False)}
    return ret

import json
import urllib.request
from typing import Any, Dict

SQL_URL = 'http://172.30.8.52:6174/api/v1/appstore/audit/sql-query'
SQL_ID_RESULT = '20260626002'

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _first_row(resp):
    if not isinstance(resp, dict):
        return {}
    rows = resp.get('execute_sql_resp') or resp.get('executeSqlResp') or []
    if isinstance(rows, list) and rows and isinstance(rows[0], dict):
        return rows[0]
    if isinstance(rows, dict):
        return rows
    return resp

def _query_one(request_ids):
    # 单品查询：返回 (ok, row, resultCode)
    body = json.dumps({'sqlId': SQL_ID_RESULT,
                       'params': 'requestIds:' + request_ids}).encode('utf-8')
    req = urllib.request.Request(SQL_URL, data=body, method='POST',
                                 headers={'Content-Type': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
    except Exception:
        return False, {}, 'E'
    return True, _first_row(resp), str(resp.get('resultCode', '0'))

async def main(args):
    p = args.params
    offers = [o for o in _load(p.get('offers')) if isinstance(o, dict)]
    if not offers:
        rid = str(p.get('requestIds') or '')
        if rid:
            offers = [{'offer_seq': 1, 'offer_id': '', 'requestIds': rid}]
    if not offers:
        ret: Output = {'pass': '', 'error_list': '', 'audit_summary': '',
                       'resultCode': '0', 'offers': '[]',
                       'fail_reason': '缺少 requestIds，请先发起稽核（环节4a）'}
        return ret
    norm = []
    err_lines = []
    sum_lines = []
    batch_pass = '1'
    result_code = '0'
    for i, o in enumerate(offers, start=1):
        seq = o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i
        offer_id = str(o.get('offer_id') or o.get('offerId') or '')
        rid = o.get('requestIds') or o.get('request_ids') or o.get('request_id') or ''
        if isinstance(rid, list):
            rid = ','.join(str(x) for x in rid if str(x))
        rid = str(rid or '')
        ok, row, rcode = _query_one(rid)
        if rcode not in ('', '0'):
            result_code = rcode
        if not ok:
            item_pass = ''
            err = '稽核结果查询失败'
            summary = ''
        else:
            raw_pass = row.get('pass')
            if raw_pass in (None, ''):
                if row.get('error_list'):
                    raw_pass = '0'
                elif str(row.get('isAllFinished', '')).lower() in ('y', 'yes', 'true', '1'):
                    raw_pass = '1'
                else:
                    raw_pass = ''
            item_pass = str(raw_pass)
            err = row.get('error_list')
            if isinstance(err, (list, dict)):
                err = json.dumps(err, ensure_ascii=False)
            err = '' if err is None else str(err)
            summary = str(row.get('audit_summary') or row.get('auditConclusion') or '')
        if item_pass != '1':
            batch_pass = '0'
        if err:
            err_lines.append('#%s %s：%s' % (seq, offer_id, err))
        if summary:
            sum_lines.append('#%s %s：%s' % (seq, offer_id, summary))
        norm.append({'offer_seq': seq, 'offer_id': offer_id,
                     'pass': item_pass, 'error_list': err, 'audit_summary': summary})
    ret: Output = {'pass': batch_pass,
                   'error_list': '\n'.join(err_lines),
                   'audit_summary': '；'.join(sum_lines),
                   'resultCode': result_code,
                   'offers': json.dumps(norm, ensure_ascii=False)}
    return ret

import json
from typing import Any, Dict

def _roster_map(raw):
    # 权威名册归一：入参可为 [{offer_seq,name,quantity}] / {offers:[...]} / JSON 字符串
    obj = raw
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if isinstance(obj, dict):
        obj = obj.get('offers')
    if not isinstance(obj, list):
        return {}
    out = {}
    for i, o in enumerate(obj, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        name = str(o.get('name') or '').strip()
        qty = o.get('quantity')
        if name or qty not in (None, ''):
            out[seq] = {'name': name, 'quantity': qty}
    return out

def _merge_roster(offers, raw):
    # 按 offer_seq 把权威名册的 name/quantity 合并进逐品元素（已有非空 name 不覆盖）
    roster = _roster_map(raw)
    if not roster or not isinstance(offers, list):
        return offers
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        r = roster.get(seq)
        if not r:
            continue
        if r.get('name') and not str(o.get('name') or '').strip():
            o['name'] = r['name']
        if r.get('quantity') not in (None, '') and o.get('quantity') in (None, ''):
            o['quantity'] = r['quantity']
    return offers

_PASSTHROUGH = ('pass', 'error_list', 'audit_summary', 'risk_list', 'compare_list',
                'requestIds', 'sales_id', 'file_id', 'globalId', 'testScenes', 'offer_id',
                'offers', 'req_id', 'plan_json')

def _any(v):
    # 平台出参可能是已序列化 JSON 字符串，也可能是原始 list/str；统一尝试解析
    if isinstance(v, (list, dict)):
        return v
    if v is None:
        return None
    s = str(v)
    if not s.strip():
        return None
    t = s.strip()
    if t[0] in '[{' and t[-1] in ']}':
        try:
            return json.loads(t)
        except Exception:
            return s
    return s

async def main(args):
    p = args.params
    env: Dict[str, Any] = {}
    for key in _PASSTHROUGH:
        if key in p and p.get(key) is not None and str(p.get(key)) != '':
            env[key] = _any(p.get(key))
    # V3.14：若提供权威名册（roster_name/roster 入参），按 offer_seq 把 name/quantity
    # 合并进落库 offers[]，保证下游销售品文案前后一致（名册缺失时零变化）。
    roster = p.get('roster') or p.get('roster_name') or ''
    if roster and isinstance(env.get('offers'), list):
        env['offers'] = _merge_roster(env['offers'], roster)
    md = str(p.get('md') or p.get('markdown') or '')
    md_key = str(p.get('md_key') or 'report_md')
    if md:
        env[md_key] = md
        # 兼容占位：老消费方仅认 raw 时可回退取值
        env.setdefault('raw', md)
    ret: Output = {
        'record_json': json.dumps(env, ensure_ascii=False)
    }
    return ret

